from typing import Union

from taf.hw.pdu.device_status import DeviceStatus
from taf.hw.pdu.devices.http_client import HttpPdu
from taf.hw.pdu.exceptions import BadPortNumber


class UTRONIX(HttpPdu):
    """Support for IP-SwitchBox800"""

    POWER_ON_STATUS = "1"
    POWER_OFF_STATUS = "0"
    POWER_ON_CODE = {
        1: "/k101000000",
        2: "/k102000000",
        3: "/k104000000",
        4: "/k108000000",
        5: "/k110000000",
        6: "/k120000000",
        7: "/k140000000",
        8: "/k180000000",
    }
    POWER_OFF_CODE = {
        1: "/k100010000",
        2: "/k100020000",
        3: "/k100040000",
        4: "/k100080000",
        5: "/k100100000",
        6: "/k100200000",
        7: "/k100400000",
        8: "/k100800000",
    }
    CHECK_CODE = "/k0"

    def __init__(self, host: str, timeout: Union[float, int] = 10) -> None:
        self._max_ports = 8
        super().__init__(host=host, timeout=timeout)

    @property
    def _port_setting(self):
        return {
            DeviceStatus.OFF: self.POWER_OFF_STATUS,
            DeviceStatus.ON: self.POWER_ON_STATUS,
        }

    def _build_request_url(self, port, status):
        port = int(port)
        self._verify_port_number(port)
        code_for_status = {
            DeviceStatus.ON: self.POWER_ON_CODE[port],
            DeviceStatus.OFF: self.POWER_OFF_CODE[port],
            None: self.CHECK_CODE,
        }
        return f"http://{self._host}{code_for_status[status]}"

    def _verify_port_number(self, port):
        if port not in range(1, self._max_ports + 1):
            exc_msg = f"Port number is invalid: {port}"
            raise BadPortNumber(exc_msg)

    def _parse_response(self, response, port):
        status_hex = response.text[:2]
        status_bin = format((int(status_hex, 16)), "08b")
        return status_bin[-port]
